import { Category, MenuItem, MenuSection } from './types';

export const DRINK_CATEGORY_SLUGS = new Set([
  'hot-drinks',
  'latte',
  'fresh-juices',
  'cold-mixes',
  'smoothies',
  'soft-drinks',
  'milkshake',
  'cocktails',
]);

export function getCategorySection(category: { slug: string; section?: MenuSection }): MenuSection {
  if (category.section === 'drinks' || category.section === 'food') {
    return category.section;
  }
  return DRINK_CATEGORY_SLUGS.has(category.slug) ? 'drinks' : 'food';
}

